106	{
107	    PTE *pgdir_kva = (PTE *)pa2kva(pgdir);
108	    int vpn2 = (va >> VPN2_SHIFT) & VPN_MASK;
109	    int vpn1 = (va >> VPN1_SHIFT) & VPN_MASK;
110	    int vpn0 = (va >> VPN0_SHIFT) & VPN_MASK;
