119	        set_pfn(l2_entry, (uintptr_t)new_table >> NORMAL_PAGE_SHIFT);
120	        set_attribute(l2_entry, _PAGE_PRESENT);
121	    }
122	    PTE *l1_table = (PTE *)pa2kva(get_pa(*l2_entry));
