139	/* find the leaf PTE (kva) mapping physical address `pa` in `pgdir` (pa) */
140	static PTE* find_pte_by_pa(PTE *pgdir, uintptr_t pa)
141	{
142	    PTE *l2_table = (PTE *)pa2kva((uintptr_t)pgdir);
143	
144	    for (int i = 0; i < NUM_PTE_ENTRY; i++) {
145	        if (i == 0x001 || i == 0x101) {
146	            continue;   /* skip the shared kernel large-page entries */
147	        }
148	        if (!get_attribute(l2_table[i], _PAGE_PRESENT)) {
149	            continue;
150	        }
151	        PTE *l1_table = (PTE *)pa2kva(get_pa(l2_table[i]));
152	        for (int j = 0; j < NUM_PTE_ENTRY; j++) {
153	            if (!get_attribute(l1_table[j], _PAGE_PRESENT)) {
154	                continue;
155	            }
156	            PTE *l0_table = (PTE *)pa2kva(get_pa(l1_table[j]));
157	            for (int k = 0; k < NUM_PTE_ENTRY; k++) {
158	                if (get_attribute(l0_table[k], _PAGE_PRESENT) &&
159	                    get_pa(l0_table[k]) == pa) {
160	                    return &l0_table[k];
161	                }
162	            }
163	        }
164	    }
165	    return NULL;
166	}
