313	uintptr_t shm_page_get(int key)
314	{
315	    int slot = key % SHM_PAGE_NUM;
316	    pcb_t *cur = current_running[cpu_id];
317	
318	    /* allocate the shared physical page on first use */
319	    if (shm_page[slot].count == 0) {
320	        uintptr_t pa = alloc_user_page(1, NULL);    /* pinned: never swapped */
321	        memset((void *)pa2kva(pa), 0, PAGE_SIZE);
322	        shm_page[slot].pa = pa;
323	    }
324	
325	    /* find a free virtual address in the shared memory region */
326	    uintptr_t va;
327	    for (va = SHM_BASE; va < SHM_END; va += PAGE_SIZE) {
328	        PTE *pte = walk_page_table(va, (uintptr_t)cur->pgdir, 0);
329	        if (pte == NULL || !get_attribute(*pte, _PAGE_PRESENT)) {
330	            break;
331	        }
332	    }
333	    if (va >= SHM_END) {
334	        if (shm_page[slot].count == 0) {
335	            free_user_page(shm_page[slot].pa);
336	        }
337	        return 0;
338	    }
339	
340	    /* map the shared page into the current process */
341	    PTE *pte = walk_page_table(va, (uintptr_t)cur->pgdir, 1);
342	    set_pfn(pte, shm_page[slot].pa >> NORMAL_PAGE_SHIFT);
343	    set_attribute(pte, _PAGE_PRESENT | _PAGE_READ | _PAGE_WRITE |
344	                  _PAGE_USER | _PAGE_ACCESSED | _PAGE_DIRTY);
345	    shm_page[slot].count++;
346	    flush_tlb_all();
347	
348	    return va;
349	}
