351	/*
352	 * allocate a fresh user page and map `va` to it in `pgdir` (pa);
353	 * if the page is already mapped it is kept.  Returns the kva of the
354	 * mapped page.
355	 */
356	uintptr_t alloc_map_user_page(uintptr_t va, uintptr_t pgdir)
357	{
358	    va = ROUNDDOWN(va, PAGE_SIZE);
359	    PTE *pte = walk_page_table(va, pgdir, 1);
360	
361	    if (!get_attribute(*pte, _PAGE_PRESENT)) {
362	        ptr_t pa = alloc_user_page(0, (PTE *)pgdir);
363	        memset((void *)pa2kva(pa), 0, PAGE_SIZE);
364	        set_pfn(pte, pa >> NORMAL_PAGE_SHIFT);
365	        set_attribute(pte, _PAGE_PRESENT | _PAGE_READ | _PAGE_WRITE |
366	                      _PAGE_EXEC | _PAGE_USER | _PAGE_ACCESSED | _PAGE_DIRTY);
367	    }
368	
369	    return get_kva_of(va, pgdir);
370	}
