372	void shm_page_dt(uintptr_t addr)
373	{
374	    pcb_t *cur = current_running[cpu_id];
375	    uintptr_t va = ROUNDDOWN(addr, PAGE_SIZE);
376	
377	    PTE *pte = walk_page_table(va, (uintptr_t)cur->pgdir, 0);
378	    if (pte == NULL || !get_attribute(*pte, _PAGE_PRESENT)) {
379	        return;
380	    }
381	
382	    uintptr_t pa = get_pa(*pte);
383	
384	    /* unmap the page from the current process */
385	    *pte = 0;
386	    flush_tlb_all();
387	
388	    /* decrease the reference count of the shared page */
389	    for (int s = 0; s < SHM_PAGE_NUM; s++) {
390	        if (shm_page[s].count > 0 && shm_page[s].pa == pa) {
391	            if (--shm_page[s].count == 0) {
392	                free_user_page(pa);
393	            }
394	            break;
395	        }
396	    }
397	}
