184	        int binsem_id = kill_pcb->binsem_id[--kill_pcb->binsem_num];
185	        binsem_node_t *node = &binsem_nodes[binsem_id];
186	        if (!list_empty(&node->block_queue)) {
187	            do_unblock(node->block_queue.next);
188	        } else {
189	            node->sem++;
190	        }
191	    }
192	
193	    /* wake up all the processes waiting for the victim */
194	    while (!list_empty(&kill_pcb->wait_list)) {
195	        do_unblock(kill_pcb->wait_list.next);
196	    }
197	
198	    if (kill_pcb->status == TASK_RUNNING) {
199	        /* the victim is running on another core: mark it as killed,
200	           it will be reaped by the scheduler of that core */
201	        kill_pcb->status = TASK_KILLED;
202	    } else {
203	        /* the victim is in some queue: remove it and hand it
204	           over to the reaper of core 0 */
205	        list_del(&kill_pcb->list);
206	        kill_pcb->status = TASK_EXITED;
207	        list_add_tail(&kill_pcb->list, &kernel_pcb[0].wait_list);
208	    }
