void scheduler(void)
{
    pcb_t *prev_running = current_running[cpu_id];
    pcb_t *next_running;
    list_node_t *next_node;

    /* put the current task back to the ready queue if it is
       still running (i.e. not blocked, exited or killed) */
    if (prev_running->status == TASK_RUNNING) {
        prev_running->status = TASK_READY;
        prev_running->ready_tick = get_ticks();
        list_add_tail(&prev_running->list, &ready_queue);
    } else if (prev_running->status == TASK_KILLED) {
        /* the task was killed while running on this core: release
           its address space and hand it over to the reaper of core 0 */
        free_process_user_page(prev_running->pgdir);
        prev_running->status = TASK_EXITED;
        list_add_tail(&prev_running->list, &kernel_pcb[0].wait_list);
    }

    /* pick the ready task with the highest priority that is
       allowed to run on this core */
    next_node = max_priority_node();
    if (next_node == NULL) {
        /* nothing else to run, keep the current task */
        return;
    }
    list_del(next_node);

    next_running = list_entry(next_node, pcb_t, list);
    next_running->status = TASK_RUNNING;
    next_running->cpu_id = cpu_id;
    current_running[cpu_id] = next_running;
    current_cpu_running = next_running;

    /* switch to the address space of the next task (the kernel
       mappings are shared by all page tables, so it is safe to
       switch satp while executing kernel code) */
    set_satp(SATP_MODE_SV39, 0,
             ((uintptr_t)next_running->pgdir >> NORMAL_PAGE_SHIFT));

    /* restore the cursor location of the next task */
    screen_move_cursor(next_running->cursor_x, next_running->cursor_y);
}

pid_t do_exec(const char* file_name, int argc, char* argv[], spawn_mode_t mode)
{
    #define EXEC_MAX_ARGC 16

    /* locate the ELF file to execute */
    unsigned char *binary;
    int length;
    if (!get_elf_file(file_name, &binary, &length)) {
        return -1;
    }

    /* search for a free pcb */
    int i;
    for (i = 0; i < NUM_MAX_TASK; i++) {
        if (pcb[i].pid == -1) {
            break;
        }
    }
    if (i == NUM_MAX_TASK) {
        return -1;
    }

    /* allocate the kernel stack (pinned: it is accessed through the
       kernel direct map and must never be swapped out) */
    pcb[i].kernel_sp = pa2kva(alloc_user_page(1, NULL) + PAGE_SIZE);
    pcb[i].user_sp = USER_STACK_ADDR;
    pcb[i].kernel_stack_base = pcb[i].kernel_sp;
    pcb[i].user_stack_base = pcb[i].user_sp;

    /* create the virtual address space and load the ELF binary */
    pcb[i].pgdir = init_page_table();
    uintptr_t entry = load_elf(binary, length, (uintptr_t)pcb[i].pgdir,
                               alloc_map_user_page);
    if (entry == 0) {
        /* not a valid ELF: roll back the allocations */
        free_process_user_page(pcb[i].pgdir);
        free_user_page(kva2pa(pcb[i].kernel_stack_base - PAGE_SIZE));
        return -1;
    }

    /* copy the arguments onto the user stack: the strings are placed
       top-down below USER_STACK_ADDR, followed by the argv pointer
       array; the stack pointer is set to the argv array */
    if (argc > EXEC_MAX_ARGC) {
        argc = EXEC_MAX_ARGC;
    }
    uintptr_t stack_kva =
        alloc_map_user_page(USER_STACK_ADDR - PAGE_SIZE, (uintptr_t)pcb[i].pgdir);
    uintptr_t va = USER_STACK_ADDR;
    uintptr_t kva = stack_kva + PAGE_SIZE;

    enable_sum();   /* argv points into the caller's user space */
    reg_t argv_va[EXEC_MAX_ARGC];
    for (int n = 0; n < argc; n++) {
        int len = strlen(argv[n]) + 1;
        kva -= len;
        va -= len;
        memcpy((void *)kva, argv[n], len);
        argv_va[n] = (reg_t)va;
    }
    disable_sum();

    kva = ROUNDDOWN(kva, sizeof(reg_t));
    va = ROUNDDOWN(va, sizeof(reg_t));
    kva -= (argc + 1) * sizeof(reg_t);
    va -= (argc + 1) * sizeof(reg_t);
    for (int n = 0; n < argc; n++) {
        ((reg_t *)kva)[n] = argv_va[n];
    }
    ((reg_t *)kva)[argc] = 0;
    pcb[i].user_sp = va;

    /* initialize the pcb */
    pcb[i].preempt_count = 0;
    init_list_head(&pcb[i].wait_list);
    pcb[i].binsem_num = 0;
    pcb[i].pid = process_id++;
    pcb[i].type = USER_PROCESS;
    pcb[i].status = TASK_READY;
    pcb[i].mode = mode;
    pcb[i].priority = 0;
    pcb[i].ready_tick = get_ticks();
    pcb[i].mask = 3;
    pcb[i].cursor_x = 1;
    pcb[i].cursor_y = 1;

    /* initialize the stack: ra, sp, gp, a0, a1, sstatus, sepc, sscratch */
    regs_context_t *pt_regs =
        (regs_context_t *)(pcb[i].kernel_sp - sizeof(regs_context_t));
    pcb[i].kernel_sp -= sizeof(regs_context_t);
    pt_regs->regs[1] = (reg_t)entry;                // ra
    pt_regs->regs[2] = (reg_t)pcb[i].user_sp;       // sp
    pt_regs->regs[3] = (reg_t)__global_pointer$;    // gp
    pt_regs->regs[10] = (reg_t)argc;                // a0
    pt_regs->regs[11] = (reg_t)pcb[i].user_sp;      // a1 (argv)
    pt_regs->sstatus = (reg_t)SR_SPIE;              // SPP = 0, SPIE = 1
    pt_regs->sepc = (reg_t)entry;                   // sepc
    pt_regs->sscratch = (reg_t)&pcb[i];             // sscratch = tp

    /* add the new task into the ready queue */
    list_add_tail(&pcb[i].list, &ready_queue);

    return pcb[i].pid;
}

void do_exit()
{
    pcb_t *exit_pcb = current_running[cpu_id];

    /* release all the binary semaphores held by this process */
    while (exit_pcb->binsem_num > 0) {
        binsem_op(exit_pcb->binsem_id[exit_pcb->binsem_num - 1],
                  BINSEM_OP_UNLOCK);
    }

    /* wake up all the processes waiting for this process */
    while (!list_empty(&exit_pcb->wait_list)) {
        do_unblock(exit_pcb->wait_list.next);
    }

    /* release the virtual address space of this process (the kernel
       stack is released later by the reaper) */
    free_process_user_page(exit_pcb->pgdir);

    if (exit_pcb->mode == ENTER_ZOMBIE_ON_EXIT) {
        /* become a zombie and wait to be reaped by waitpid */
        exit_pcb->status = TASK_ZOMBIE;
    } else {
        /* AUTO_CLEANUP_ON_EXIT: hand the pcb over to the reaper */
        exit_pcb->status = TASK_EXITED;
        list_add_tail(&exit_pcb->list, &kernel_pcb[0].wait_list);
    }

    /* switch to another task */
    scheduler();
}

