            read_superblock();
            superblock->used_inode_num++;
            write_superblock();

            return i;
        }
    }
    return 0xffff;
}

// Returns block id
uint32_t alloc_block()
{
    read_blockmap();
    uint8_t *map = (uint8_t *)BLOCKMAP_CACHE;

    /* scan the block bitmap for the first free block
       (64 sectors * 512 bytes * 8 bits = 262144 blocks) */
    for (uint32_t i = 0; i < 64 * 512 * 8; i++) {
        if (!(map[i / 8] & (1u << (i % 8)))) {
            map[i / 8] |= (1u << (i % 8));
            write_blockmap();

            read_superblock();
            superblock->used_block_num++;
            write_superblock();

            return i;
        }
    }
    return 0xffffffff;
}

void free_inode(uint16_t inode_id)
{
    read_inodemap();
    uint8_t *map = (uint8_t *)INODEMAP_CACHE;

    map[inode_id / 8] &= ~(1u << (inode_id % 8));
    write_inodemap();

    read_superblock();
    superblock->used_inode_num--;
    write_superblock();
}

void free_block(uint32_t block_id)
{
    read_blockmap();
    uint8_t *map = (uint8_t *)BLOCKMAP_CACHE;

    map[block_id / 8] &= ~(1u << (block_id % 8));
    write_blockmap();

    read_superblock();
    superblock->used_block_num--;
    write_superblock();
}

