   on success returns 1 and stores the entry in `out`, the block id
   holding it in `out_block` and its index in `out_index` (the latter
   two may be NULL) */
int find_in_dir(uint16_t dir_inode_id, const char* name, dir_entry_t* out,
                uint32_t* out_block, int* out_index)
{
    inode_t dir_inode = *(inode_t*)read_inode(dir_inode_id);

    for (int b = 0; b < 10 && (uint32_t)(b * 4096) < dir_inode.size; b++) {
        read_block(dir_inode.direct_blocks[b]);
        dir_t *dir = (dir_t*)BLOCK_CACHE;
        for (int i = 0; i < 128; i++) {
            if (dir->entry[i].type != EMPTY &&
                strcmp((char*)dir->entry[i].name, name) == 0) {
                *out = dir->entry[i];
                if (out_block != 0) {
                    *out_block = dir_inode.direct_blocks[b];
                }
                if (out_index != 0) {
                    *out_index = i;
                }
                return 1;
            }
        }
    }
    return 0;
}

/* add an entry to the directory `dir_inode_id`, allocating a new
   block for the directory when all the existing ones are full */
int add_dir_entry(uint16_t dir_inode_id, uint8_t type, const char* name,
                  uint16_t inode_id)
{
    inode_t *dir_inode = (inode_t*)read_inode(dir_inode_id);

    for (int b = 0; b < 10; b++) {
        if ((uint32_t)(b * 4096) >= dir_inode->size) {
            /* all the existing blocks are full: allocate a new one */
            uint32_t nb = alloc_block();
            if (nb == 0xffffffff) {
                return 0;
            }
            dir_inode->direct_blocks[b] = nb;
            dir_inode->size += 4096;
            write_inode(dir_inode_id);

            memset((void*)BLOCK_CACHE, 0, 4096);
            dir_t *dir = (dir_t*)BLOCK_CACHE;
            dir->entry[0].type = type;
            strcpy((char*)dir->entry[0].name, name);
            dir->entry[0].inode = inode_id;
            write_block(nb);
            return 1;
        }

        uint32_t bid = dir_inode->direct_blocks[b];
        read_block(bid);
        dir_t *dir = (dir_t*)BLOCK_CACHE;
        for (int i = 0; i < 128; i++) {
            if (dir->entry[i].type == EMPTY) {
                dir->entry[i].type = type;
                strcpy((char*)dir->entry[i].name, name);
                dir->entry[i].inode = inode_id;
                write_block(bid);
                return 1;
            }
        }
    }
    return 0;
}

