    if (name[0] == '\0' || strcmp(name, ".") == 0 || strcmp(name, "..") == 0) {
        return 0;
    }

    /* the directory must exist */
    dir_entry_t entry;
    uint32_t entry_block;
    int entry_index;
    if (!find_in_dir(current_dir_inode, name, &entry, &entry_block, &entry_index) ||
        entry.type != DIR) {
        return 0;
    }

    /* the directory must be empty (only "." and ".." are allowed) */
    inode_t dir_inode = *(inode_t*)read_inode(entry.inode);
    for (int b = 0; b < 10 && (uint32_t)(b * 4096) < dir_inode.size; b++) {
        read_block(dir_inode.direct_blocks[b]);
        dir_t *dir = (dir_t*)BLOCK_CACHE;
        for (int i = 0; i < 128; i++) {
            if (dir->entry[i].type != EMPTY &&
                strcmp((char*)dir->entry[i].name, ".") != 0 &&
                strcmp((char*)dir->entry[i].name, "..") != 0) {
                return 0;
            }
        }
    }

    /* release the blocks and the inode of the directory */
    for (int b = 0; b < 10 && (uint32_t)(b * 4096) < dir_inode.size; b++) {
        free_block(dir_inode.direct_blocks[b]);
    }
    free_inode(entry.inode);

    /* remove the entry from the current directory */
    read_block(entry_block);
    ((dir_t*)BLOCK_CACHE)->entry[entry_index].type = EMPTY;
    write_block(entry_block);

    return 1;
}

int do_ls(char* dirname, int mode, int* print_location_y)
{
    char name[32];
    fs_get_name(name, dirname);

    /* an empty name means the current working directory */
    uint16_t dir_inode_id = current_dir_inode;
    if (name[0] != '\0') {
        dir_entry_t entry;
        if (!find_in_dir(current_dir_inode, name, &entry, 0, 0) ||
            entry.type != DIR) {
            return 0;
        }
        dir_inode_id = entry.inode;
    }

    int lines = 0;
    for (int b = 0; b < 10; b++) {
        inode_t dir_inode = *(inode_t*)read_inode(dir_inode_id);
        if ((uint32_t)(b * 4096) >= dir_inode.size) {
            break;
        }
        read_block(dir_inode.direct_blocks[b]);
        dir_t *dir = (dir_t*)BLOCK_CACHE;
        for (int i = 0; i < 128; i++) {
            if (dir->entry[i].type == EMPTY) {
                continue;
            }
            if (mode == 0) {
                /* short listing: hide "." and ".." */
                if (strcmp((char*)dir->entry[i].name, ".") == 0 ||
                    strcmp((char*)dir->entry[i].name, "..") == 0) {
                    continue;
                }
                prints("%s\n", dir->entry[i].name);
            } else {
                /* long listing: show the type, inode and size */
                dir_entry_t entry = dir->entry[i];
                inode_t inode = *(inode_t*)read_inode(entry.inode);
                prints("%s    type: %s    inode: %d    size: %d    link: %d\n",
                       entry.name,
                       entry.type == DIR ? "dir" : "file",
                       entry.inode, inode.size, inode.link);
            }
            lines++;
        }
    }

    enable_sum();
    *print_location_y = *print_location_y + lines;
    disable_sum();

    return 1;
}

int do_cd(char* dirname)
{
    char name[32];
    fs_get_name(name, dirname);
    if (name[0] == '\0') {
        return 0;
    }

    /* "cd /" goes back to the root directory */
    if (strcmp(name, "/") == 0) {
        current_dir_inode = superblock->root_inode_id;
        current_dir_block = superblock->root_block_id;
        return 1;
    }

    dir_entry_t entry;
    if (!find_in_dir(current_dir_inode, name, &entry, 0, 0) ||
        entry.type != DIR) {
        return 0;
    }

    inode_t dir_inode = *(inode_t*)read_inode(entry.inode);
    current_dir_inode = entry.inode;
    current_dir_block = dir_inode.direct_blocks[0];

    return 1;
}

int do_link(char* filename, char* newfile, int mode)
{
    char src_name[32], new_name[32];
    fs_get_name(src_name, filename);
    fs_get_name(new_name, newfile);
    if (src_name[0] == '\0' || new_name[0] == '\0') {
        return 0;
    }

    /* the source must exist and the target must not */
    dir_entry_t src_entry;
    if (!find_in_dir(current_dir_inode, src_name, &src_entry, 0, 0)) {
        return 0;
    }
    dir_entry_t tmp;
    if (find_in_dir(current_dir_inode, new_name, &tmp, 0, 0)) {
        return 0;
    }

    if (mode == 0) {
        /* hard link: the new entry points to the same inode */
        if (!add_dir_entry(current_dir_inode, src_entry.type, new_name,
                           src_entry.inode)) {
            return 0;
        }
        inode_t *inode = (inode_t*)read_inode(src_entry.inode);
        inode->link++;
        write_inode(src_entry.inode);
    } else {
        /* soft link: a new file whose content is the source path */
        uint16_t new_inode = alloc_inode();
        if (new_inode == 0xffff) {
            return 0;
        }
        uint32_t new_block = alloc_block();
        if (new_block == 0xffffffff) {
            free_inode(new_inode);
            return 0;
        }

        memset((void*)BLOCK_CACHE, 0, 4096);
        strcpy((char*)BLOCK_CACHE, src_name);
        write_block(new_block);

        inode_t *inode = (inode_t*)read_inode(new_inode);
        memset(inode, 0, sizeof(inode_t));
        inode->mode = FILE;
        inode->owner = 0;
        inode->size = strlen(src_name) + 1;
        inode->direct_blocks[0] = new_block;
        inode->link = 1;
        write_inode(new_inode);

        if (!add_dir_entry(current_dir_inode, FILE, new_name, new_inode)) {
            free_block(new_block);
            free_inode(new_inode);
            return 0;
        }
    }

    return 1;
}

